function drawWorld(){
 const palettes=[['#172326','#283235','#51463a','#746044'],['#171d26','#30333b','#55515a','#8e7655'],['#171f24','#303a3b','#494b42','#837358']][level];
 let sky=ctx.createLinearGradient(0,0,0,GROUND);sky.addColorStop(0,palettes[0]);sky.addColorStop(1,palettes[1]);ctx.fillStyle=sky;ctx.fillRect(cam-2,0,W+4,GROUND);
 // moon / storm glow
 ctx.globalAlpha=.22;ctx.fillStyle=level===2?'#c06c48':'#d7cba3';ctx.beginPath();ctx.arc(cam+375,47,24,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // distant hills and ruined roofs
 ctx.fillStyle='#192425';ctx.beginPath();ctx.moveTo(cam-20,174);for(let x=0;x<=W+40;x+=24)ctx.lineTo(cam+x,138+rand(Math.floor((cam+x)/24)+level*90)*27);ctx.lineTo(cam+W+40,GROUND);ctx.lineTo(cam-20,GROUND);ctx.fill();
 for(let x=Math.floor(cam/124)*124-124;x<cam+W+160;x+=124){let sx=x+rand(x+8)*45,bh=45+rand(x+19)*40;
 if(level===0){ // village shack silhouettes
 rect(sx,GROUND-bh,45,bh,'#282d29');ctx.fillStyle='#302b26';ctx.beginPath();ctx.moveTo(sx-8,GROUND-bh+7);ctx.lineTo(sx+22,GROUND-bh-12);ctx.lineTo(sx+52,GROUND-bh+6);ctx.fill();rect(sx+9,GROUND-bh+20,7,12,'#8b6940');rect(sx+30,GROUND-bh+22,6,6,'#a7864f');rect(sx+2,GROUND-7,50,5,'#433c31');
 }else if(level===1){rect(sx,GROUND-bh-12,54,bh+12,'#343238');rect(sx+7,GROUND-bh,9,20,'#22282a');rect(sx+33,GROUND-bh+9,10,26,'#24292a');rect(sx-5,GROUND-bh-17,64,7,'#474046');rect(sx+24,GROUND-bh+25,9,20,'#786441');}
 else {rect(sx,GROUND-bh,49,bh,'#2a302d');rect(sx+6,GROUND-bh+8,8,7,'#a34c32');rect(sx+33,GROUND-bh+20,8,6,'#a34c32');rect(sx+23,GROUND-14,4,14,'#483f33');}
 }
 // hanging clouds / particles
 for(let n=0;n<18;n++){let px=cam+((n*83+frame*.12)%560)-40,py=38+(n*31%105);rect(px,py,12+(n%4)*4,1,'#aeb4a22b');}
 // ground
 rect(cam-10,GROUND,W+30,H-GROUND,'#292920');rect(cam-10,GROUND,W+30,4,'#626047');
 for(let x=Math.floor(cam/16)*16;x<cam+W+16;x+=16){let seed=Math.floor(x/16);rect(x,GROUND+4,15,2,rand(seed+2)>.5?'#343329':'#262820');if(rand(seed+6)>.6)rect(x+5,GROUND+8,2,3,'#554a37');if(rand(seed+1)>.78)rect(x+11,GROUND-5,2,5,'#8b7651');}
 // scattered grave markers, fences and debris
 for(let x=Math.floor(cam/95)*95;x<cam+W+100;x+=95){let r=rand(x+level*3);if(r>.43){rect(x,GROUND-16,3,16,'#403e34');rect(x-3,GROUND-16,9,3,'#514c3d');rect(x+4,GROUND-9,1,7,'#6c634a');}else{rect(x,GROUND-5,13,3,'#443a2d');rect(x+4,GROUND-8,6,3,'#514331');}}
 for(const p of platforms){rect(p.x,p.y,p.w,5,level===1?'#71624b':'#514c3d');rect(p.x,p.y,p.w,2,'#9b8355');for(let x=p.x+5;x<p.x+p.w;x+=11)rect(x,p.y+5,2,5,'#37332d');}
 // gate at the far end
 let gx=LEVEL_LENGTH-86;rect(gx,GROUND-59,8,59,'#5a5140');rect(gx+68,GROUND-59,8,59,'#5a5140');rect(gx,GROUND-62,76,6,'#82704f');for(let x=gx+10;x<gx+70;x+=10){rect(x,GROUND-52,4,52,'#796849');rect(x+4,GROUND-53,2,53,'#242624');}rect(gx+29,GROUND-34,18,34,'#1c2020');
 // dropped items
 for(const p of pickups){if(p.taken)continue;let y=p.y+Math.sin(frame*.09+p.x)*2;if(p.type==='herb'){rect(p.x-5,y-6,10,7,'#354d32');rect(p.x-1,y-9,3,5,'#6a9651');rect(p.x+1,y-5,3,4,'#8bad5b');}else{rect(p.x-5,y-6,10,7,'#9a8051');rect(p.x-4,y-8,3,2,'#c7a86c');}}
 for(const b of bullets){rect(b.x-2,b.y,5,2,weapons[hero.weapon].color);}
 for(const b of enemyBullets){rect(b.x-2,b.y-1,5,3,'#e18a51');}
 for(const en of enemies){if(en.hp<=0)continue;drawEnemy(en);}
 drawHero();for(const p of particles){rect(p.x,p.y,2,2,p.color);}
 // level landmark labels
 if(cam<250)text(level===0?'VALDELOBOS  •  00:17':'',24,209,6,'#aaa38c');
}
function drawHero(){let x=Math.round(hero.x),y=Math.round(hero.y),f=hero.face;
 if(hero.inv>0&&Math.floor(frame/4)%2===0)return;
 // shadow
 rect(x-2,GROUND-2,16,2,'#111513aa');
 // boots / legs
 rect(x+2,y+17,4,4,'#262724');rect(x+7,y+17,4,4,'#292a27');rect(x+1,y+20,6,2,'#171a1a');rect(x+7,y+20,6,2,'#171a1a');
 // blue jacket torso
 rect(x+2,y+8,9,10,'#4e6370');rect(x+1,y+11,11,5,'#394d59');rect(x+3,y+8,7,2,'#74818a');rect(x+9,y+10,3,5,'#293b45');
 // neck, face, hair
 rect(x+4,y+5,5,4,'#d4a47b');rect(x+3,y+3,7,4,'#c99770');rect(x+3,y+2,8,3,'#b4a58c');rect(x+3,y+1,7,2,'#5a5148');rect(x+8,y+5,1,1,'#181a19');
 // arm and handgun
 rect(x+(f>0?9:0),y+9,4,3,'#c5936f');if(f>0){rect(x+10,y+10,7,2,'#292b2a');rect(x+15,y+9,4,2,'#494a43');}else{rect(x-5,y+10,7,2,'#292b2a');rect(x-8,y+9,4,2,'#494a43');}
 if(flash>0){let mx=f>0?x+20:x-9;rect(mx,y+8,5,4,'#f8e6a1');rect(mx+(f>0?2:-2),y+6,3,8,'#ffb355');flash--;}
}
function drawEnemy(e){let x=Math.round(e.x),y=Math.round(e.y),f=e.dir;rect(x-2,GROUND-2,e.w+4,2,'#12151499');
 let skin=e.hurt>0?'#d18b6e':e.type==='brute'?'#756d60':'#93866c',cloth=e.type==='brute'?'#514c44':'#4a4b3b';
 // shambling legs, torso and head
 rect(x+2,y+e.h-7,4,6,'#35352f');rect(x+8,y+e.h-7,4,6,'#34342e');rect(x+1,y+e.h-2,6,2,'#252622');rect(x+8,y+e.h-2,6,2,'#252622');
 rect(x+2,y+8,e.w-4,e.h-15,cloth);rect(x+1,y+10,3,8,skin);rect(x+e.w-4,y+10,4,8,skin);rect(x+3,y+1,e.w-6,8,skin);rect(x+3,y,e.w-6,3,'#55483b');
 rect(x+(f>0?e.w-5:3),y+4,2,2,'#c2523d');if(e.type==='brute'){rect(x-1,y+3,4,5,'#6b624f');rect(x+e.w-3,y+3,4,5,'#6b624f');}
 if(Math.abs(hero.x-e.x)<185){rect(x,y-7,e.w,2,'#201b18');rect(x,y-7,e.w*(e.hp/e.max),2,'#b25040');}
}
function drawHud(){if(state==='title')return;
 // compact top panel
 rect(8,8,165,31,'#101515dc');rect(8,8,2,31,'#a88148');text('LEON S. KENNEDY',16,18,7,'#d9d3be');rect(16,23,87,7,'#382b26');rect(17,24,clamp(hero.hp,0,100)*.84,5,hero.hp>35?'#8a382f':'#c44735');text(`${Math.ceil(hero.hp)}%`,108,30,7,'#c9bda2');
 // right stage / objective panel
 rect(350,8,122,31,'#101515dc');text(`CHAPTER 0${level+1}`,460,18,7,'#d5c9a9','right');text(stageNames[level],460,29,8,'#e8dfc7','right');
 rect(8,246,464,16,'#0c1110df');rect(8,246,3,16,'#a88148');let w=weapons[hero.weapon];text(w.name,16,257,8,'#ead69d');text(`${hero.reload>0?'RELOADING…':String(hero.ammo[hero.weapon]).padStart(2,'0')+' / '+String(hero.reserve[hero.weapon]).padStart(2,'0')}`,105,257,8,'#e6e1d1');text('1  PISTOL   2  SHOTGUN   3  RIFLE',221,257,6,'#aaa995');text(`KILLS ${String(kills).padStart(2,'0')}`,463,257,7,'#d3c9b0','right');
 // progress line
 rect(0,0,480,2,'#262b28');rect(0,0,480*(hero.x/LEVEL_LENGTH),2,'#a97b40');
 if(toastTime>0){rect(147,50,186,19,'#101515e8');text(toast,240,63,8,'#e6cc83','center');}
 if(state==='playing'&&frame<330){text('MOVE  A / D     JUMP  SPACE     FIRE  F     RELOAD  R',240,235,6,'#e0d9c4aa','center');}
}

