function drawChapter(){rect(0,0,W,H,'#070a0bdc');panel();text(`CHAPTER 0${storyIndex+1}  /  03`,240,70,7,'#b9a477','center');text(story[storyIndex].title,240,97,13,'#e1d4b3','center');rect(112,107,256,1,'#6c5a3b');let words=story[storyIndex].text.split(' '),line='',rows=[];for(const word of words){let test=line?line+' '+word:word;if(test.length>47){rows.push(line);line=word}else line=test}if(line)rows.push(line);rows.forEach((s,i)=>text(s,240,128+i*12,7,'#c2c0b3','center'));text('OBJECTIVE: REACH THE EXIT  •  LEAVE NO ONE BEHIND',240,174,7,'#bd9b5b','center');text('PRESS ENTER / TAP TO CONTINUE',240,201,8,'#eee0ba','center');}
