function drawHud(){if(state==='title')return;rect(8,8,165,31,'#101515dc');rect(8,8,2,31,'#a88148');text('LEON S. KENNEDY',16,18,7,'#d9d3be');rect(16,23,87,7,'#382b26');rect(17,24,clamp(hero.hp,0,100)*.84,5,hero.hp>35?'#8a382f':'#c44735');text(`${Math.ceil(hero.hp)}%`,108,30,7,'#c9bda2');rect(350,8,122,31,'#101515dc');text(`CHAPTER 0${level+1}`,460,18,7,'#d5c9a9','right');text(stageNames[level],460,29,8,'#e8dfc7','right');rect(8,246,464,16,'#0c1110df');rect(8,246,3,16,'#a88148');let w=weapons[hero.weapon];text(w.name,16,257,8,'#ead69d');text(`${hero.reload>0?'RELOADING…':String(hero.ammo[hero.weapon]).padStart(2,'0')+' / '+String(hero.reserve[hero.weapon]).padStart(2,'0')}`,105,257,8,'#e6e1d1');text('1 PISTOL   2 SHOTGUN   3 RIFLE',221,257,6,'#aaa995');text(`KILLS ${String(kills).padStart(2,'0')}`,463,257,7,'#d3c9b0','right');rect(0,0,480,2,'#262b28');rect(0,0,480*(hero.x/LEVEL_LENGTH),2,'#a97b40');if(toastTime>0){rect(147,50,186,19,'#101515e8');text(toast,240,63,8,'#e6cc83','center')}if(state==='playing'&&frame<330)text('MOVE A / D     JUMP SPACE     FIRE F     RELOAD R',240,235,6,'#e0d9c4aa','center');}
canvas.addEventListener('pointerdown',()=>{if(state==='title')startGame();else if(state==='chapter'){resetStage(storyIndex);state='playing'}else if(state==='dead'||state==='win')state='title'});
for(const button of document.querySelectorAll('.touch-btn')){const k=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(k==='reload')reload();else keys[k]=true});const release=e=>{e.preventDefault();keys[k]=false};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)}
let prev=0;function loop(now){let dt=prev?Math.min(now-prev,40):16.67;prev=now;update(dt);draw();requestAnimationFrame(loop)}hero.y=GROUND-hero.h;requestAnimationFrame(loop);
})();</script></body></html>

